package com.nua.assistant.presence.companion

import java.util.Base64
import org.bouncycastle.crypto.params.Ed25519PrivateKeyParameters
import org.bouncycastle.crypto.params.Ed25519PublicKeyParameters
import org.bouncycastle.crypto.signers.Ed25519Signer
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The digest/signature below were generated by running the *actual* companion
 * implementation (services/companion/nua_companion/security.py) against fixed inputs:
 *
 *   canonical_request(1, "req-123", "device-abc", "nonce-xyz", 1700000000000,
 *                      "inference.start", '{"modelId":"local-model","prompt":"hello"}')
 *   digest_request(...).hex()
 *   compact_json({"prompt": "hello", "modelId": "local-model"})
 *   Ed25519PrivateKey.from_private_bytes(bytes(range(32))).sign(digest)
 *
 * This is a genuine cross-language interop check, not a self-consistency check: if
 * this implementation ever drifts from the companion's wire format, this test -- not
 * just a round trip against itself -- catches it.
 */
class CompanionSecurityTest {

    private val goldenDigestHex = "501959b9854993cf5e8db805af4b1f7206dd3160b106112d8892b8d3b68d294a"
    private val goldenPrivateSeedB64 = "AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8="
    private val goldenPublicKeyB64 = "A6EHv/POEL4dcN0Y50vAmWfk1jCbpQ1fHdyGZBJVMbg="
    private val goldenSignatureB64 = "X8G0ZyR2fKbmewR+5jhOTh+GXs6hVMWj8hZYuaK8iUxSItQXI4pv2tFq03Q2X0AJGO+7sC4spbt7G8lBq1P8BA=="

    @Test
    fun `digestRequest matches the companion's own output for the same inputs`() {
        val digest = CompanionSecurity.digestRequest(
            protocolVersion = 1,
            requestId = "req-123",
            clientId = "device-abc",
            nonce = "nonce-xyz",
            timestampMillis = 1700000000000,
            operation = "inference.start",
            payloadJson = """{"modelId":"local-model","prompt":"hello"}""",
        )

        assertEquals(goldenDigestHex, digest.joinToString("") { "%02x".format(it) })
    }

    @Test
    fun `compactJson sorts keys and matches Python's json dumps with sort_keys`() {
        val compact = CompanionSecurity.compactJson(mapOf("prompt" to "hello", "modelId" to "local-model"))

        assertEquals("""{"modelId":"local-model","prompt":"hello"}""", compact)
    }

    @Test
    fun `compactJson escapes non-ASCII text exactly like Python's ensure_ascii default`() {
        // Built from explicit character codes, not escape-sequence or literal non-ASCII
        // text in this source file, to rule out any ambiguity in how this file's own
        // text was transmitted/encoded. Golden value: compact_json({"prompt":
        // "héllo 世界 \t\n", "modelId": ""}) from the real companion.
        val eAcute = 0x00e9.toChar()
        val shi = 0x4e16.toChar()
        val jie = 0x754c.toChar()
        val input = "h" + eAcute + "llo " + shi + jie + " \t\n"
        val backslash = 0x5c.toChar()
        val expectedEscaped = "h${backslash}u00e9llo ${backslash}u4e16${backslash}u754c ${backslash}t${backslash}n"

        val compact = CompanionSecurity.compactJson(mapOf("prompt" to input, "modelId" to ""))

        assertEquals("{\"modelId\":\"\",\"prompt\":\"$expectedEscaped\"}", compact)
    }

    @Test
    fun `a BouncyCastle Ed25519 public key accepts the companion's own signature over the golden digest`() {
        // Recomputed via digestRequest, not re-decoded, so this also proves
        // digestRequest's own output is literally what got signed on the Python side.
        val digest = CompanionSecurity.digestRequest(1, "req-123", "device-abc", "nonce-xyz", 1700000000000, "inference.start", """{"modelId":"local-model","prompt":"hello"}""")
        val publicKey = Ed25519PublicKeyParameters(Base64.getDecoder().decode(goldenPublicKeyB64), 0)
        val signature = Base64.getDecoder().decode(goldenSignatureB64)

        val verifier = Ed25519Signer()
        verifier.init(false, publicKey)
        verifier.update(digest, 0, digest.size)

        assertTrue("a signature produced by the real companion must verify here", verifier.verifySignature(signature))
    }

    @Test
    fun `signing the golden digest with the same private key reproduces the companion's exact signature`() {
        val privateKey = Ed25519PrivateKeyParameters(Base64.getDecoder().decode(goldenPrivateSeedB64), 0)
        val digest = CompanionSecurity.digestRequest(1, "req-123", "device-abc", "nonce-xyz", 1700000000000, "inference.start", """{"modelId":"local-model","prompt":"hello"}""")

        val signer = Ed25519Signer()
        signer.init(true, privateKey)
        signer.update(digest, 0, digest.size)
        val signature = signer.generateSignature()

        // Ed25519 is deterministic: the same key + message always yields the same
        // signature, so this must be byte-identical to what Python produced.
        assertArrayEquals(Base64.getDecoder().decode(goldenSignatureB64), signature)
    }

    @Test
    fun `isWithinClockSkew rejects a timestamp more than 120 seconds away`() {
        val now = 1_700_000_000_000L

        assertTrue(CompanionSecurity.isWithinClockSkew(now - 119_000, now))
        assertTrue(!CompanionSecurity.isWithinClockSkew(now - 121_000, now))
    }
}
